-- Synthetic 002-shaped prerequisite, ONLY for the network-disabled test runner.
-- Not a recovered migration, a production schema assertion, or a deployable file.
CREATE ROLE anon NOLOGIN NOSUPERUSER NOBYPASSRLS;
CREATE ROLE authenticated NOLOGIN NOSUPERUSER NOBYPASSRLS;
CREATE SCHEMA auth;
CREATE TABLE auth.users (id uuid PRIMARY KEY);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS
$$ SELECT nullif(current_setting('request.jwt.claim.sub', true), '')::uuid $$;
GRANT USAGE ON SCHEMA auth, public TO anon, authenticated;
CREATE TABLE public.grocery_list_members (
  list_id uuid NOT NULL, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  PRIMARY KEY (list_id, user_id)
);
CREATE TABLE public.grocery_items (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  created_at timestamptz NOT NULL DEFAULT now(), item_name text,
  purchased boolean DEFAULT false, list_id uuid, quantity bigint DEFAULT 1,
  owner_id uuid REFERENCES auth.users(id)
);
CREATE TABLE public.grocery_list_invites (
  token uuid PRIMARY KEY DEFAULT gen_random_uuid(), list_id uuid NOT NULL,
  created_by uuid NOT NULL REFERENCES auth.users(id),
  expires_at timestamptz NOT NULL DEFAULT now() + interval '1 day'
);
-- Fail closed: this fixture does not certify the deployed invitation helper.
CREATE FUNCTION public.create_grocery_list_invite(uuid) RETURNS uuid
LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Invitation fixture unavailable'; END $$;
ALTER TABLE public.grocery_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.grocery_list_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.grocery_list_invites ENABLE ROW LEVEL SECURITY;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.grocery_items, public.grocery_list_members
  TO anon, authenticated;
GRANT USAGE ON SEQUENCE public.grocery_items_id_seq TO authenticated;
CREATE POLICY "Users can view their own list memberships" ON public.grocery_list_members
  FOR SELECT USING (user_id = auth.uid());
CREATE POLICY "Members can add grocery items" ON public.grocery_items FOR INSERT
  WITH CHECK (EXISTS (SELECT FROM public.grocery_list_members m
    WHERE m.list_id = grocery_items.list_id AND m.user_id = auth.uid()));
CREATE POLICY "Members can read grocery items" ON public.grocery_items FOR SELECT
  USING (EXISTS (SELECT FROM public.grocery_list_members m
    WHERE m.list_id = grocery_items.list_id AND m.user_id = auth.uid()));
CREATE POLICY "Members can update grocery items" ON public.grocery_items FOR UPDATE
  USING (EXISTS (SELECT FROM public.grocery_list_members m
    WHERE m.list_id = grocery_items.list_id AND m.user_id = auth.uid()))
  WITH CHECK (EXISTS (SELECT FROM public.grocery_list_members m
    WHERE m.list_id = grocery_items.list_id AND m.user_id = auth.uid()));
CREATE POLICY "Members can delete grocery items" ON public.grocery_items FOR DELETE
  USING (EXISTS (SELECT FROM public.grocery_list_members m
    WHERE m.list_id = grocery_items.list_id AND m.user_id = auth.uid()));
